    DEVICE ZXSPECTRUM48
  ORG $5B00

; The stack
;
; The game's stack, in the printer buffer. The start (start) sets SP to
; loader_entry, so it grows down from there; the game runs with interrupts off,
; so nothing else ever lands on it. All zero in the snapshot.
stack_space:
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00

; The top of the stack
;
; The landscape renderer (after_step_drawn) does not save and restore SP around
; its POP blitter: it loads SP with this address after each piece, which must
; be where the stack stands inside draw_landscape when that is called from the
; play loop -- three calls deep, so that these six bytes are three return
; addresses and the renderer's own RET still finds its caller's (inferred from
; the reset; the chain of calls was not traced here).
stack_top:
  DEFB $00,$00,$00,$00,$00,$00

; Move the game block down and undo its nibble shift
;
; The tape's BASIC calls this once the game block has loaded, 512 bytes above
; where it runs. It ran during loading, which the build does not see, so it is
; described from reading alone. loader_copy, the copy routine the earlier PIC
; block left at the top of memory, moves the block down 512 bytes to
; game_entry; then an RRD walk down from the block's top moves every byte's
; nibbles along by one -- the tape holds the game four bits out of step -- and
; the game starts at game_entry.
;
; After the game starts these 25 bytes are dead: the view's page's
; collision-box list (see ground_cell_top_left_rest) is written over them, and
; the stack grows down from just below them.
loader_entry:
  LD SP,loader_leftover_charset ; Stack under the copy routine's home;
  DI                            ; interrupts off for good
  CALL loader_copy        ; Move the block down 512 bytes to game_entry
                          ; (loader_copy)
  LD HL,shift_tables      ; From the top of the block down, 158 times 256
  XOR A                   ; bytes; A starts at 0, so the top byte's high nibble
  LD BC,$9E00             ; becomes a zero
loader_entry_0:
  RRD                     ; RRD: (HL)'s low nibble to A, A's old low nibble to
                          ; (HL)'s high nibble, (HL)'s high nibble to its low
                          ; nibble
  DEC HL                  ; Down a byte, for every byte of the block: the whole
  DEC C                   ; block and the system variables under it, all but
  JR NZ,loader_entry_0    ; their first byte (hence the nonsense in them)
  DJNZ loader_entry_0     ;
  JP game_entry           ; Start the game

; The rest of the view's page's collision-box list
;
; The landscape renderer (draw_landscape) draws the four map cells (pages) the
; view straddles in turn -- the view's own page at the map position
; (ground_cell = 0), the one below it (1), the one to its right (2) and the one
; below and right (3) -- and keeps a list of collision boxes, 37 bytes, for
; each: loader_entry (written over the loader), ground_cell_bottom_left,
; ground_cell_top_right and ground_cell_bottom_right. find_page_boxes finds the
; list for a map column and row by comparing them with the view's own.
;
; The list: +0 the number of pieces the page's tile has (zero for a page with
; none, and for all four while the map position's row is 0, 1 or 2, when
; scroll_landscape clears them and does not call draw_landscape at all); then,
; only while record_ground is set, five bytes for each piece as it was drawn,
; written through the pointer at collision_object by draw_landscape: +0 its x,
; +1 its y, +2 and +3 its extent (worked out from the piece's direction and its
; number of steps), +4 a byte looked up by the direction. These are the
; ground's collision boxes, read by leave_slope and place_collision_box
; (through find_page_boxes and move_across). The meaning of +2 to +4 in detail
; is for those routines.
ground_cell_top_left_rest:
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00 ; Bytes 25-36 of the
                                                       ; list (its first 25 are
                                                       ; at loader_entry)

; The collision-box list of the page below the view's
;
; See ground_cell_top_left_rest for the layout. The page at the map position's
; column and the row under it (ground_cell = 1).
ground_cell_bottom_left:
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00

; The collision-box list of the page right of the view's
;
; See ground_cell_top_left_rest for the layout. The page at the next column
; (wrapping from 95 to 0) and the map position's row (ground_cell = 2).
ground_cell_top_right:
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00

; The collision-box list of the page below and right of the view's
;
; See ground_cell_top_left_rest for the layout. The page at the next column and
; the next row (ground_cell = 3). The byte after it is not used (searched).
ground_cell_bottom_right:
  DEFB $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$FF,$00,$00,$F0,$0F,$30,$D2,$D0,$30,$52,$00,$00,$00,$60,$31
  DEFB $11,$00,$60,$00,$B0
  DEFB $00                ; Not used (searched)

; A saved step across
;
; In the system variables' area, which the game has no use for, like all the
; variables from here to fuel_saver. Many of them are scratch: one routine's
; loop counter is another's flag, and routines in unrelated parts of the game
; share a byte. Each is named by its main use and its other users are listed.
; The snapshot's values are the BASIC system variables put through the loader's
; nibble shift, and mean nothing.
;
; This word is saved by bounce_shallow_negate from a moving thing's record (+7
; and +8, put through three_eighths) and added back further on in the same
; routine.
saved_step_x:
  DEFB $10,$00

; A saved step down
;
; The same as saved_step_x for the record's +9 and +10: saved and added back by
; bounce_shallow_negate. The byte after it is not used (searched).
saved_step_y:
  DEFB $10,$00
  DEFB $60                ; Not used

; How far a touch went in
;
; Written by test_landscape_piece and test_slope_reversed, which test a part of
; an object against a slope's shape: how far into the shape the part is, made
; positive. leave_slope reads it, negated, as a new step to push the object
; back out. after_step_drawn also uses it as a flag between its own
; instructions. The byte after it is not used (searched).
touch_depth:
  DEFB $00
  DEFB $00                ; Not used

; The busiest scratch byte
;
; Used by more than forty routines as a counter or a holding place. Among them:
; the slope tests (test_landscape_piece, test_slope_reversed) leave 1 in it for
; a touch, and load_map_window keeps in it the object kind it gives the pick-up
; places it puts into object slots ($0C for the first eleven, $1E for the last
; eight).
scratch_count:
  DEFB $01

; Which map cell is being drawn
;
; Which of the four map cells draw_landscape is drawing, 0-3 (see
; ground_cell_top_left_rest): bit 0 set for the lower row, bit 1 for the
; right-hand column. Elsewhere a scratch byte (ground_object_fires,
; start_attacker, next_part, place_collision_box, draw_carried_piece and
; others).
ground_cell:
  DEFB $00

; A row count
;
; Scratch, mostly a count of rows or lines: the shift-table builders
; (read_piece_header, next_shift, shift_slope_piece) count rows in it,
; reloading it from row_count_spare; start_attacker, object_box and
; test_player_shots keep a line in it; draw_beams reads it.
row_count:
  DEFB $00

; The row count's spare
;
; The copy row_count is reloaded from (read_piece_header, next_shift,
; shift_slope_piece); also scratch for start_attacker and toggle_carried_part.
row_count_spare:
  DEFB $00

; Pieces left in the tile
;
; The number of pieces left to draw in the map cell's tile: draw_landscape sets
; it from the tile's record and after_step_drawn counts it down. Also scratch
; for toggle_carried_part, next_part_boxes, hit_slope, downhill and
; shift_flat_piece. The byte after it is not used (searched).
pieces_left:
  DEFB $00
  DEFB $00                ; Not used

; Steps in the piece
;
; The number of steps in the piece being drawn: the low nibble of its third
; byte, 16 when that is 0 (draw_landscape); read again by flat_step_clip. The
; byte after it is not used (searched).
piece_steps:
  DEFB $00
  DEFB $00                ; Not used

; The piece's step down
;
; The piece's step in y, from its direction (load_piece_steps, given the sign
; of the step in x); used by after_step_drawn and fill_behind_moving_piece.
; Also written by landscape_end_pieces, and by colour_piece as a width less
; one.
piece_step_y:
  DEFB $00

; The piece's step across
;
; The size of the piece's step in x (load_piece_steps), added to its x by
; piece_ends and draw_landscape. Also a mode byte of the collision routines
; (collide_with_landscape, next_box, hit_block, hit_slope, leave_slope,
; ship_on_slope_response, place_collision_box), written by move_bouncing,
; move_or_explode, update_shot, ship_pass and build_shifted_pieces and read by
; shift_slope_piece.
piece_step_x:
  DEFB $00

; The tile is upside down
;
; $99 while the tile being drawn is turned upside down (its record starts $99),
; 0 otherwise (draw_landscape). load_piece_steps then swaps each piece's
; direction between floor and ceiling through the second half of the table at
; mirror_table, and piece_ends turns its y over (XOR $0C) and its extra bytes
; (XOR 1). Floors become ceilings: the caverns.
tile_upside_down:
  DEFB $00

; A step kept for the column fill
;
; Cleared for each piece by draw_landscape; set by flat_step_clip when it keeps
; a step's address and x for the fill behind a piece; read by
; fill_flat_end_column, which then uses the kept step.
piece_kept:
  DEFB $00

; A width in bytes
;
; Scratch, as a byte and as a word with sprite_width_drawn. The sprite routines
; keep a width less one in bytes here (draw_sprite_pair copies it and
; sprite_width_drawn before turning them into pixels); also used by
; set_old_sprite, set_direct_old, clear_sprite_pair, draw_direct_pair,
; direct_erase_row, collect_pickup, mirror_ship_sprite, carried_part,
; draw_carried_piece and draw_ship.
sprite_width:
  DEFB $00

; The width a sprite was drawn with
;
; The width a sprite was drawn with, kept to rub it out (set_new_sprite,
; set_direct_new, draw_direct_pair, direct_draw_row, colour_sprite); the high
; byte of sprite_width as a word. Also read by ship_contact, object_box,
; set_mirrored_drawer and draw_carried_piece.
sprite_width_drawn:
  DEFB $00

; How far a box sticks out to the right
;
; Kept by place_collision_box, the collision box's placement, for the part that
; sticks out past the right of the page into the next (read by part_right and
; next_part).
stick_out_right:
  DEFB $00

; How far a box sticks out above
;
; The same for what sticks out above the page's top (place_collision_box, read
; by part_above and next_part).
stick_out_up:
  DEFB $00

; The x of the piece's step
;
; Moved on by the step in x at each step of a piece (landscape_step_loop); also
; used by draw_sprite_pair, dissolve_sprite, buffer_address, part_above,
; part_right, place_collision_box, slope_step_at_left_edge, flat_step_clip and
; step_screen_address.
piece_x:
  DEFB $00

; The y of the piece's step
;
; Moved by the step in y at each step of a piece (landscape_step_loop); also
; used by buffer_address, part_above, part_right, next_part,
; place_collision_box, flat_step_clip, draw_flat_end_lip and
; step_screen_address.
piece_y:
  DEFB $00

; A move across
;
; With piece_steps_done, a word: the move across that place_collision_box keeps
; (beside moved_x) and part_right and next_part read. slope_step_at_left_edge
; writes this byte as one of its own, a count of bytes to skip.
move_across_kept:
  DEFB $00

; Steps of the piece drawn
;
; How many steps of the piece have been drawn: cleared for each piece by
; draw_landscape and counted up by after_step_drawn, which draws nothing more
; for a piece with none; also read by edge_column, draw_flat_end_lip and
; step_screen_address. Its other use is as the high byte of move_across_kept.
piece_steps_done:
  DEFB $00

; The tile is mirrored left-right
;
; $FF while the tile being drawn is mirrored left-right (its record has an $FF
; before its piece count), 0 otherwise (draw_landscape). piece_ends then
; reflects each piece's x, swaps its two extra bytes (XOR 2) and turns its
; direction round through the first half of the table at mirror_table. Also the
; low byte of a move down place_collision_box keeps for part_above and
; next_part.
tile_mirrored_left_right:
  DEFB $00

; The view's edge flags
;
; Which of the view's edges a step or an object has crossed: cleared at each
; step by landscape_step_loop, set and tested by the clipping routines
; column_at_view_bottom, column_at_view_top, column_at_view_left and
; column_at_view_right; also written by prepare_draw and read by steer_to_view.
edge_flags:
  DEFB $00

; The piece reverses
;
; Set by column_at_view_bottom and column_at_view_top when a piece's steps
; reverse at an edge, cleared for each piece by draw_landscape, read by
; fill_behind_moving_piece.
piece_clip:
  DEFB $00

; A flat piece's first extra byte
;
; The first of the two extra bytes a piece of direction 0 or 7 carries
; (piece_ends; with the tile mirrored left-right it is the second, XOR 2;
; upside down, XOR 1). Read by flat_step_clip and fill_flat_end_column, and by
; landscape_end_pieces and first_piece_shift as a word with piece_extra_b.
piece_extra_a:
  DEFB $00

; A flat piece's second extra byte
;
; The second; a $16 is left as it is by both reversals. Read by colour_piece,
; flat_step_clip, draw_flat_end_lip, fill_flat_end_column,
; fill_behind_moving_piece and last_piece_width.
piece_extra_b:
  DEFB $00

; The piece is a ceiling
;
; $80 when the piece's direction is 7 or more, the ceiling shapes
; (set_piece_shape); cleared for each piece by draw_landscape; read by
; after_step_drawn and fill_behind_moving_piece. The collision routines
; (next_box, hit_block, hit_slope, place_collision_box) also keep in it what
; has happened this pass, bit 7 a block hit and bit 4 a slope.
piece_ceiling:
  DEFB $00

; Which way the ship was pushed
;
; Cleared by move_ship every pass and set there from the controls: $80 pushed
; left, 3 right, 0 not. draw_ship turns the ship's facing towards it;
; accelerate_across reads it too.
steer_push:
  DEFB $C0

; This pass's controls
;
; In the Kempston layout (bit 0 right, 1 left, 2 down, 3 up, 4 fire), as
; read_controls leaves them; move_ship forces 8 (thrust) while the stage is
; ending. Read by fire, special_beam_key, end_special_beam, draw_ship,
; lift_jet, and by random, which stirs it into the random number.
controls_now:
  DEFB $03

; The ship's line
;
; The ship's line on the screen, the line its shots fly along: set by
; build_ship_sprite from the ship's record (+$1E, less the ship's height, plus
; 9) and by toggle_carried_part; read by ship_contact, draw_beams, update_shot,
; fire, place_shot, carried_part, draw_carried_piece, draw_ship, lift_jet and
; start_landscape.
ship_line:
  DEFB $04

; The gun's cooling count
;
; Set to 6 by fire when it fires a shot and counted down there every pass; it
; fires again only once the count is 0. draw_ship clears it.
gun_cooling:
  DEFB $F0

; A colour for the view's page row
;
; Written by set_landscape_colours from one of two bytes kept with the view's
; four tile numbers (see load_map_window), chosen by whether the map row is
; above 12 or not; read by colour_piece.
map_row_colour:
  DEFB $DF

; A colour for the page row below
;
; The same as map_row_colour for the row below; read by colour_piece.
map_row_colour_next:
  DEFB $0C

; The view is being built
;
; Nonzero while the view is being built afresh rather than played: $FF from
; start_landscape at the start of a life, 3 from fly_in_step, 0 when play goes
; on. While it is set draw_beams returns at once and load_map_window puts no
; objects into slots; with bit 7 set, load_map_window draws map tile $3E as
; tile $AA (two of its six pieces). draw_landscape copies a nonzero value to
; record_ground.
map_rebuild:
  DEFB $D0

; Record the collision boxes
;
; Set from map_rebuild by draw_landscape and by scroll_landscape: while it is
; nonzero, draw_landscape writes a collision box for each piece it draws into
; the map cell's list (ground_cell_top_left_rest), so the ground's boxes are
; made when the view is built rather than at every pass.
record_ground:
  DEFB $DF

; The ship's top speed across
;
; 2, or 4 when +$0A of the current player's record (score) (an add-on) is set
; (build_ship_sprite); read by draw_ship, accelerate_across and
; clamp_speed_across, which hold the speed to it.
top_speed:
  DEFB $05

; The ship's top climb
;
; 2, or 4 when +$0B of the record (an add-on) is set (build_ship_sprite); set
; to 4 by move_ship while the stage is ending, and read there and by
; clamp_climb.
top_climb:
  DEFB $00

; Halve the fuel burn
;
; Set to $FF by ship_contact, and every pass copied away (to last_pass_contact)
; and cleared by update_objects; read by move_ship and ship_on_slope_response.
; While it is set the fuel burn at the end of read_controls is halved (again,
; after any halving for +$0C of the current player's record).
fuel_saver:
  DEFB $00

; Unused: what is left of the system variables
;
; Nothing refers to these bytes (searched). They are the BASIC system variables
; the loader found here, put through its nibble shift.
basic_leftovers:
  DEFB $10,$00,$F0,$1F,$00,$C0,$70,$00,$00,$80,$D5,$05,$00,$60,$CB,$B5
  DEFB $CB,$B5,$CC,$85,$D5,$A5,$CC,$95,$D5,$C5,$D5,$75,$D5,$35,$DB,$E5
  DEFB $D5,$E5,$D5,$E5,$D5,$D5,$22,$C9,$05,$20,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$D0,$A9,$01,$00,$B0,$00,$00,$80,$F5,$0F,$00,$10,$02

; Game entry
;
; Used by the routine at loader_entry.
;
; Where the loader (loader_entry) jumps once the game is in place: interrupts
; off -- the game never turns them on -- and on to the start.
game_entry:
  DI                      ; Interrupts off
  JP start                ; Start the game (start)

; Bit-doubling table
;
; Sixteen bytes, one for each value of a nibble: each of the nibble's four bits
; doubled into a pair, so that bit n of the index sets bits 2n and 2n+1.
; print_char_double prints characters twice as wide this way (and twice as
; tall, by writing each row twice), looking up each half of a font byte: it
; adds the nibble to $84 with B holding $5C, so the table has to sit within one
; page.
double_bits:
  DEFB $00,$03,$0C,$0F,$30,$33,$3C,$3F
  DEFB $C0,$C3,$CC,$CF,$F0,$F3,$FC,$FF

; The things lying in the world: their kinds
;
; The world's 290 objects -- the things lying in the landscape at fixed places,
; as opposed to the attackers -- are kept in three parallel tables: this one,
; one byte each; map_object_places, two bytes each (where); and
; map_objects_per_column, how many there are in each map column. They are in
; column order, so the objects of column C start at the sum of the counts of
; the columns before it (spawn_column_objects).
;
; Each byte here: bits 0-5 the object's kind, 0-16, which
; spawn_objects_from_list copies into the object slot's +$13 and looks up in
; the table at object_kind_flags (bits 5-7 of that entry go into the slot's
; +$18, and with bit 4 set the slot's graphic is $1B instead of $0D, an
; animated object whose frame byte and frame range come from
; object_part_pairs); bit 7 set once player 1 has taken or destroyed the
; object, bit 6 once player 2 has (ship_hits_ground_objects and
; beam_hits_ground_object find the byte again from the slot's +$18 bit 0 and
; +$19, which hold its number), after which it never comes back for that
; player: play patches the BIT 7 in spawn_objects_from_list and the SET 7s in
; ship_hits_ground_objects and beam_hits_ground_object to bit 6 while player 2
; plays. mask_world_objects ANDs every byte with a mask: $3F at a new game
; (new_game), so bits 6 and 7 are cleared and everything comes back; at the end
; of a planet (planet_secured) a mask from the player in play (player_in_play),
; $7F for player 1 and $BF for player 2, so that only that player's objects
; come back.
;
; Read by spawn_column_objects and spawn_objects_from_list each time the screen
; moves to a new map column. Laid out below a line per map column, the kinds of
; that column's objects, from the game's bytes when the disassembly is built.
map_object_kinds:
  DEFB $06,$08            ; Column 0: kinds 6, 8
  DEFB $02,$0D            ; Column 1: kinds 2, 13
  DEFB $0F,$07,$03,$0E,$10,$0A ; Column 2: kinds 15, 7, 3, 14, 16, 10
  DEFB $02,$05            ; Column 3: kinds 2, 5
  DEFB $01,$04            ; Column 4: kinds 1, 4
  DEFB $06,$00,$10        ; Column 5: kinds 6, 0, 16
  DEFB $02,$05            ; Column 6: kinds 2, 5
  DEFB $0B                ; Column 7: kind 11
  DEFB $07,$04,$0E        ; Column 8: kinds 7, 4, 14
  DEFB $0F,$04            ; Column 9: kinds 15, 4
  DEFB $0B,$06,$05,$0D    ; Column 10: kinds 11, 6, 5, 13
  DEFB $10,$10            ; Column 11: kinds 16, 16
  DEFB $0F,$03,$05,$10,$08 ; Column 12: kinds 15, 3, 5, 16, 8
  DEFB $01,$05            ; Column 13: kinds 1, 5
  DEFB $07,$02            ; Column 14: kinds 7, 2
  DEFB $06,$0A            ; Column 15: kinds 6, 10
  DEFB $0F,$01            ; Column 16: kinds 15, 1
  DEFB $02,$0A,$0E,$04    ; Column 17: kinds 2, 10, 14, 4
  DEFB $04,$0E,$0C,$0E    ; Column 18: kinds 4, 14, 12, 14
  DEFB $07,$04,$01        ; Column 19: kinds 7, 4, 1
  DEFB $08                ; Column 20: kind 8
  DEFB $0B,$06,$05        ; Column 21: kinds 11, 6, 5
  DEFB $02,$09            ; Column 22: kinds 2, 9
  DEFB $0B,$04,$02,$05,$0D,$08 ; Column 23: kinds 11, 4, 2, 5, 13, 8
  DEFB $04,$06,$02,$05,$0D ; Column 24: kinds 4, 6, 2, 5, 13
  DEFB $0F,$04,$04        ; Column 25: kinds 15, 4, 4
  DEFB $07,$01            ; Column 26: kinds 7, 1
  DEFB $0F,$02,$0D,$10    ; Column 27: kinds 15, 2, 13, 16
  DEFB $07,$03            ; Column 28: kinds 7, 3
  DEFB $0C                ; Column 29: kind 12
  DEFB $06,$0E,$02,$00    ; Column 30: kinds 6, 14, 2, 0
  DEFB $0D                ; Column 31: kind 13
  DEFB $0F,$08,$05        ; Column 32: kinds 15, 8, 5
  DEFB $0C                ; Column 33: kind 12
  DEFB $07,$09,$08        ; Column 34: kinds 7, 9, 8
  DEFB $0D                ; Column 35: kind 13
  DEFB $0B,$0F,$0E,$00    ; Column 36: kinds 11, 15, 14, 0
  DEFB $06,$01,$05        ; Column 37: kinds 6, 1, 5
  DEFB $0F                ; Column 38: kind 15
  DEFB $0F,$02,$0A,$04    ; Column 39: kinds 15, 2, 10, 4
  DEFB $04,$01,$0E,$0D,$00 ; Column 40: kinds 4, 1, 14, 13, 0
  DEFB $07                ; Column 41: kind 7
