  DEFB $00,$00,$2C,$00,$00 ;
  DEFB $00,$00,$6E,$00,$00 ;
  DEFB $00,$00,$CF,$00,$00 ;
  DEFB $00,$00,$9F,$00,$00 ;
  DEFB $00,$00,$00,$00,$00 ;
