  DEFB $67,$00,$00        ;
  DEFB $5B,$C0,$00        ;
  DEFB $5F,$E0,$00        ;
  DEFB $3D,$F4,$00        ;
  DEFB $38,$7B,$00        ;
  DEFB $3D,$95,$86        ;
  DEFB $1B,$EA,$C6        ;
  DEFB $0B,$F5,$40        ;
