; Spare
;
; Twenty zero bytes; the first two are read by the mirrored direction 13 at a
; shift of 2 (slope_10_shifted).
spare_after_pieces:
  DEFS $14

; The play area's colour patch
;
; For fill_attributes, painted by colour_play_area: 28 cells wide, 20 deep, and
; the attribute -- the third byte, which start_landscape sets for each level (0
; at first, then the level's colour from its table).
play_area_colour:
  DEFB $1C,$14,$43        ; Width, depth, attribute

; The menu's text
;
; Twelve messages for print_string, printed by menu through print_strings: each
; a pixel x, a pixel y, an attribute (bit 7 set for the title), a count of
; characters, and the characters in the game's font codes ($00 to $19 the
; letters, $1A to $23 the digits, $26 a space, $28 a dash; $25 and $27 two
; special glyphs, and $2A to $2C the pieces of the rule under the title). In
; order: the title, the one- and two-player lines, the start line, the four
; control methods (the two joystick lines in two parts each), the copyright
; line and the rule. The code map split them into many small entries; their
; bytes run on to colour_ship.
menu_text:
  DEFB $48,$17,$C5,$07,$02,$18,$01,$04
  DEFB $11,$14,$0D,$50,$2F,$43,$0C,$00
  DEFB $26,$28,$26,$1B,$26,$0F,$0B,$00
  DEFB $18,$04,$11,$50,$3F,$43,$0D,$01
  DEFB $26,$28,$26,$1C,$26,$0F,$0B,$00
  DEFB $18,$04,$11,$12,$50,$4F,$46,$0E
  DEFB $1A,$26,$28,$26,$12,$13,$00,$11
  DEFB $13,$26,$06,$00,$0C,$04,$60,$67
  DEFB $45,$08,$0A,$04,$18,$01,$0E,$00
  DEFB $11,$03,$60,$77,$44,$08,$0A,$04
  DEFB $0C,$0F,$12,$13,$0E,$0D,$60,$7F
  DEFB $46,$08,$09,$0E,$18,$12,$13,$08
  DEFB $02,$0A,$68,$8F,$44,$06,$02,$14
  DEFB $11,$12,$0E,$11,$60,$97,$46,$08
  DEFB $09,$0E,$18,$12,$13,$08,$02,$0A
  DEFB $58,$A7,$44,$0B,$08,$0D,$13,$04
  DEFB $11,$05,$00,$02,$04,$26,$25,$50
  DEFB $BF,$72,$0C,$26,$26,$00,$27,$02
  DEFB $27,$06,$27,$1B,$23,$22,$1F,$40
  DEFB $21,$47,$10,$2A,$2B,$2B,$2B,$2B
  DEFB $2B,$2B,$2B,$2B,$2B,$2B,$2B,$2B
  DEFB $2B,$2B,$2C

; Colour the player's ship
;
; Used by the routine at draw_ship_image.
;
; Called once a pass by draw_ship. Works out the ship's attribute and paints it
; over the ship with the colour patch at ship_colour_patch (6 cells wide, as
; many deep as the ship's height in ship_height needs): white ($47) as a rule,
; yellow ($46) when the ore count at ore has reached 18, and while the
; hit-immunity timer shield_timer runs, cyan ($45) -- flashing between cyan and
; the usual colour every 8 passes (bit 3 of the pass counter pass_counter) in
; its last 32. A change of colour from the last one used (kept in the patch's
; third byte) makes a short sound through sound_ship_colour.
;
; The ore count ore goes up (to 18 at most) at load_ore while the rocket part
; carried (rocket_part_carried) is part 6, the one that needs 18 ore.
colour_ship:
  LD B,$47                ; White, or yellow with 18 ore aboard
  LD A,(ore)              ;
  CP $12                  ;
  JR NZ,colour_ship_0     ;
  LD B,$46                ;
colour_ship_0:
  LD C,B                  ; C keeps it
  LD A,(shield_timer)     ; Is the hit-immunity timer running?
  AND A                   ;
  JR Z,colour_ship_1      ;
  LD B,$45                ; Cyan; steady while the timer is 32 or more
  CP $20                  ;
  JR NC,colour_ship_1     ;
  LD A,(pass_counter)     ; In its last 32, the usual colour every other 8
  AND $08                 ; passes
  JR Z,colour_ship_1      ;
  LD B,C                  ;
colour_ship_1:
  LD A,($F201)              ; A sound if the colour has changed
  CP B                      ;
  PUSH BC                   ;
  CALL NZ,sound_ship_colour ;
  POP BC                    ;
  LD HL,(ship_screen_x)   ; Where the ship is on the screen
  LD A,(ship_height)      ; Its height in character rows, rounded up
  ADD A,$07               ;
  SRL A                   ;
  SRL A                   ;
  SRL A                   ;
  LD C,A                  ;
  LD ($F200),BC           ; Into the patch: depth and attribute
  LD DE,ship_colour_patch ; Paint it
  JP fill_attributes      ;

; The ship's colour patch
;
; Three bytes for fill_attributes: the width in cells (6), the depth in cells
; and the attribute, the last two written by colour_ship every pass.
ship_colour_patch:
  DEFB $06,$02,$47

; The menu frame's corners
;
; Four corners of seven bytes, read by draw_frame through +9 of the frame
; record (menu_frame): a pixel position word for the corner's graphic (only its
; place: draw_frame always draws the four bitmaps from corner_bitmaps, the
; panel frame's own, with draw_bitmap), a position word for its colour, and a
; fill_attributes colour patch (width, depth, attribute).
menu_frame_corners:
  DEFB $00,$BE,$00,$BF,$20,$01,$72 ; Top left
  DEFB $F8,$BE,$00,$07,$20,$01,$72 ; Top right
  DEFB $00,$07,$00,$B7,$01,$16,$72 ; Bottom left
  DEFB $F8,$07,$F8,$B7,$01,$16,$72 ; Bottom right

; The menu frame's tick marks
;
; Six pairs, read by draw_frame through +12 of the frame record: an x used for
; a tick on the top and bottom edges, and a y used for one on the left and
; right edges.
menu_frame_ticks:
  DEFB $20,$26            ; x, y
  DEFB $40,$4E            ;
  DEFB $68,$76            ;
  DEFB $90,$9E            ;
  DEFB $B8,$9E            ;
  DEFB $D8,$9E            ;

; The menu frame record
;
; The 17-byte record draw_frame draws the menu's frame from, given to it in IX
; by menu. The play area's frame is drawn from a record of the same shape by
; draw_panel.
menu_frame:
  DEFB $C0,$57,$DF,$57    ; The screen addresses of the tops of the left and
                          ; right edges
  DEFB $B0                ; Their height in rows
  DEFB $E1,$56,$01,$46    ; The screen addresses of the top and bottom edges
  DEFW $0000              ; The corners (menu_frame_corners, set by menu)
  DEFB $06                ; The number of tick-mark pairs
  DEFW $0000              ; The tick marks (menu_frame_ticks, set by menu)
  DEFB $06                ; The y of the top tick marks
  DEFB $F8                ; The x of the right-hand ones
  DEFB $1F                ; The length of the top and bottom edges, in bytes

; Stir the random numbers
;
; Used by the routines at deal_places, menu_loop and play.
;
; Called once a pass of the play loop (play), of the menu's loop (menu_loop)
; and from deal_places. The two random bytes of random_a are stirred with a
; byte read from a pointer that walks through memory (kept big-endian after
; them), and with the player's controls as they were last read (controls_now).
; Bits 4 and 6 of the pointer's high byte are cleared and it never reaches the
; top 20K, so the bytes come from the ROM and the game's own code.
random:
  LD IX,random_a          ; Step the pointer on, kept within the ROM and the
  LD H,(IX+$02)           ; code
  LD L,(IX+$03)           ;
  INC HL                  ;
  LD A,H                  ;
  AND $AF                 ;
  LD (IX+$02),A           ;
  LD (IX+$03),L           ;
  LD B,(HL)               ; The byte there
  LD A,(controls_now)     ; First random byte: add the byte, the controls and 5
  ADD A,B                 ;
  ADD A,$05               ;
  ADD A,(IX+$00)          ;
  LD (IX+$00),A           ;
  LD A,B                  ; Second: add the byte's complement, the controls and
  CPL                     ; 9
  LD B,A                  ;
  LD A,(controls_now)     ;
  ADD A,$09               ;
  ADD A,B                 ;
  ADD A,(IX+$01)          ;
  LD (IX+$01),A           ;
  RET

; Show the menu and wait for a game to be started
;
; Used by the routine at game.
;
; Called by game before each game. Clears the screen, draws the frame from
; menu_frame_ticks, prints the twelve lines of text at menu_text with
; print_strings, puts the two small glyphs of the copyright line (player_count)
; and colours them, draws a rule under the title, shows the two players'
; control methods (move_method_arrow), plays the title tune at title_tune until
; a key is pressed (play_tune_until_key), runs the menu's loop menu_loop until
; 0 starts a game, and plays the start tune at start_tune to the end.
menu:
  CALL clear_pixels       ; Clear the pixels, attributes to white on black
  CALL clear_attributes   ;
  LD IX,menu_frame         ; The frame, with its corners and tick marks
  LD DE,menu_frame_corners ;
  LD (IX+$09),E            ;
  LD (IX+$0A),D            ;
  LD DE,menu_frame_ticks   ;
  LD (IX+$0C),E            ;
  LD (IX+$0D),D            ;
  CALL draw_frame          ;
  LD DE,menu_text         ; The twelve lines of text
  LD B,$0C                ;
  CALL print_strings      ;
  LD HL,$BF40             ; The two glyphs on the copyright line
  LD DE,copyright_glyphs  ;
  CALL draw_bitmap        ;
  LD HL,$BEB0             ;
  CALL draw_bitmap        ;
  LD A,$46                ; Their colour
  LD ($5AE9),A            ;
  LD ($5AF6),A            ;
  LD HL,$486C             ; A rule under the title
  LD (HL),$0F             ;
  INC L                   ;
  LD B,$06                ;
menu_0:
  LD (HL),$FF             ;
  INC L                   ;
  DJNZ menu_0             ;
  LD (HL),$F0             ;
  LD IX,player1_pointer    ; Show each player's control method
  LD DE,pointer_p1_graphic ;
  CALL move_method_arrow   ;
  LD IX,player2_pointer    ;
  LD DE,pointer_p2_graphic ;
  CALL move_method_arrow   ;
  CALL menu_show_players   ; The title tune, until a key is pressed
  LD DE,title_tune         ;
  CALL play_tune_until_key ;
  CALL menu_loop          ; The menu's keys, until 0
  CALL menu_show_players  ; The start tune, played to the end
  LD DE,start_tune        ;
  JP play_tune            ;

; Number of players
;
; The first byte is the number of players less one: 0 one, 1 two (set by the
; menu's keys, menu_keys). Read by new_game, lose_life, game_over and the menu.
player_count:
  DEFB $00

; Two glyphs for the menu's copyright line
;
; The two, as draw_bitmap draws them (three times the size).
;
; Drawn by menu with draw_bitmap, one after the other: a width in bytes, a
; height in rows, and the rows. A copyright sign (3 bytes by 8 rows) and two
; letters (2 bytes by 6 rows).
copyright_glyphs:
  DEFB $03,$08            ; 3 bytes, 8 rows
  DEFB $00,$01,$3C
  DEFB $FC,$83,$42
  DEFB $FE,$C7,$99
  DEFB $03,$C7,$A1
  DEFB $03,$C7,$A1
  DEFB $FE,$C7,$99
  DEFB $FC,$83,$42
  DEFB $00,$01,$3C
  DEFB $02,$06            ; 2 bytes, 6 rows
  DEFB $81,$3F
  DEFB $C3,$7F
  DEFB $C3,$C0
  DEFB $C3,$C0
  DEFB $C3,$7F
  DEFB $81,$3F

; Clear B bytes from HL
;
; Used by the routines at reset_for_life, clear_player_record and
; build_shifted_pieces.
;
;   HL the first byte
;   B how many
; O:HL the byte after the last
clear_bytes:
  LD (HL),$00
  INC HL
  DJNZ clear_bytes
  RET

; Reset the play for a new life
;
; Used by the routine at play.
;
; Called by play at the start of every life (and of every level). Sets the
; ship's colour back to white, clears the death byte death_count, the
; hit-immunity timer shield_timer, the end-of-level byte launch_state, the hit
; count and two more flags, and empties or resets the game's tables: bit 0 of
; the first byte of 18 two-byte entries of star_layer_pointer, 96 bytes at
; shot_records, the first byte of the eight 5-byte entries of
; rocket_part_table, 16 bytes of beam_grace's table; then copies four records
; back from the starting copies that follow them (trail_frame, lift_jet_record,
; side_jet_record, and the 32 bytes of the ship's state in bare_ship), and
; resets with free_object the nine 24-byte records at object_records and the
; six 26-byte records at ground_objects.
;
; Which of these tables is which is for the ranges that hold them; here they
; are named by address only.
reset_for_life:
  LD A,$47                ; The ship's colour back to white
  LD ($F201),A            ;
  XOR A                      ; Clear the death byte, the immunity timer, the
  LD (death_count),A         ; end of the level, the hits and two more flags
  LD (shield_timer),A        ;
  LD (launch_state),A        ;
  LD (hit_count),A           ;
  LD (carried_part_redraw),A ;
  LD (meteor_shower),A       ;
  LD A,$18                ; beam_grace to 24
  LD (beam_grace),A       ;
  LD HL,star_positions    ; Bit 0 of the first byte of 18 entries of
  LD B,$12                ; star_layer_pointer
reset_for_life_0:
  LD A,(HL)               ;
  AND $FE                 ;
  LD (HL),A               ;
  INC HL                  ;
  INC HL                  ;
  DJNZ reset_for_life_0   ;
  LD HL,shot_records      ; 96 bytes at shot_records
  LD B,$60                ;
  CALL clear_bytes        ;
  LD HL,rocket_part_table ; The first byte of the eight 5-byte entries of
  LD B,$08                ; rocket_part_table
reset_for_life_1:
  LD (HL),$00             ;
  LD A,$05                ;
  CALL add_a_to_hl        ;
  DJNZ reset_for_life_1   ;
  LD HL,flicker_beam_records ; 16 bytes of beam_grace's table
  LD B,$10                   ;
  CALL clear_bytes           ;
  LD DE,trail_frame       ; Four records back to their starting values
  LD HL,trail_start       ;
  LD BC,$0006             ;
  LDIR                    ;
  LD DE,lift_jet_record   ;
  LD HL,lift_jet_start    ;
  LD C,$06                ;
  LDIR                    ;
  LD DE,side_jet_record   ;
  LD HL,side_jet_start    ;
  LD C,$07                ;
  LDIR                    ;
  LD C,$20                ;
  LD DE,ship_record       ;
  LD HL,ship_record_start ;
  LDIR                    ;
  LD IX,object_records    ; Reset the nine records at object_records
  LD B,$09                ;
  LD DE,$0018             ;
  CALL reset_for_life_2   ;
  LD IX,ground_objects    ; And the six at ground_objects
  LD E,$1A                ;
  LD B,$06                ;
reset_for_life_2:
  CALL free_object        ; The loop: B records of DE bytes from IX
  ADD IX,DE               ;
  DJNZ reset_for_life_2   ;
  RET                     ;

; Clear a player record for a new game
;
; Used by the routine at new_game.
;
; Zeroes the first 28 bytes of the record (score, flags, lives, add-ons,
; level), sets the rocket part carried (+26) to $FF (none), and copies the
; starting restart position from start_position into +19 to +24. The rest of
; the record (the control method at +28, and the table of the level's objects
; from +29) is set by new_game.
;
; HL the record (messages_and_players + 25 for player 1, + 130 for player 2)
clear_player_record:
  LD B,$1C                ; Zero +0 to +27
  PUSH HL                 ;
  CALL clear_bytes        ;
  DEC HL                  ; +26: no rocket part carried
  DEC HL                  ;
  LD (HL),$FF             ;
  POP HL                  ; +19 to +24: the restart position at the start of
  LD A,$13                ; the game
  CALL add_a_to_hl        ;
  LD DE,start_position    ;
  LD C,$06                ;
  EX DE,HL                ;
  LDIR                    ;
  RET                     ;

; The restart position at the start of a game
;
; Three words copied by clear_player_record into a player record's +19 to +24,
; the place in the landscape a life starts from (see messages_and_players): the
; values of view_column, view_x and origin_x to restore. Taken from those
; variables by save_restart_point when the restart position moves on, and put
; back by start_landscape.
;
; The origins here are $78 and $40 against a view x and y of $90 and $B7: the x
; pair sums to 8 as origin_x says it always does, but the y pair sums to $F7,
; not $B7 (origin_y). A vertical move keeps the sum (scroll_landscape adds the
; step to the origin and takes it from the view's y), and only a wrap into the
; next cell sets the pair afresh, to $B7 and 0 or $17 and $A0; so from a new
; game's start the sum is $F7 until the fly-in's first vertical wrap. Why, and
; what the first passes look like, is not known (read only).
start_position:
  DEFW $070D              ; view_column, view_x, origin_x
  DEFW $B790              ;
  DEFW $4078              ;

; Set up a new game
;
; Used by the routine at game.
;
; Called by game after the menu. Clears bits 6 and 7 of the 290 bytes from
; map_object_kinds (mask_world_objects with E = $3F): each player's mark on the
; level's objects, bit 7 for player 1 and bit 6 for player 2 (see play). Clears
; both player records (clear_player_record) and gives each five lives; if the
; score lines were left the other way round by the last game (the byte at
; p1_lives_text is $A0) they are put back with swap_players, player_in_play
; being set to $99 meanwhile so that it does not also change the current
; player. Player 1 is current; with one player, player 2 has no lives. Each
; player's control method is copied from the menu, the two scores on the panel
; are set to six noughts ($1A is the font's 0), and each player's table of the
; level's objects is filled in by deal_places.
new_game:
  LD E,$3F                ; Clear both players' marks on the level's objects
  CALL mask_world_objects ;
  LD HL,score               ; Clear both records
  CALL clear_player_record  ;
  LD HL,other_player_record ;
  CALL clear_player_record  ;
  LD A,$05                ; Five lives each
  LD (lives),A            ;
  LD ($F656),A            ;
  LD A,$99                ; Put the score lines back in order if they were
  LD (player_in_play),A   ; swapped
  LD A,(p1_lives_text)    ;
  CP $A0                  ;
  CALL Z,swap_players     ;
  XOR A                   ; Player 1 is current
  LD (player_in_play),A   ;
  LD A,(player_count)     ; One player: player 2 has no lives
  AND A                   ;
  JR NZ,new_game_0        ;
  LD ($F656),A            ;
new_game_0:
  LD A,($870A)            ; Each player's control method, as chosen on the menu
  LD (control_method),A   ;
  LD A,($870D)            ;
  LD ($F66C),A            ;
  LD B,$06                ; Both scores to 000000
  LD DE,p1_score_digits   ;
  LD HL,p2_score_digits   ;
  LD A,$1A                ;
new_game_1:
  LD (DE),A               ;
  LD (HL),A               ;
  INC HL                  ;
  INC DE                  ;
  DJNZ new_game_1         ;
  LD DE,player_places     ; Each player's table of the level's objects
  CALL deal_places        ;
  LD DE,$F66D             ;
  CALL deal_places        ;
  RET                     ; Done

; Colour the play area
;
; Used by the routines at start_landscape and fly_in_step.
;
; Paints the play area's attributes with the colour patch play_area_colour (28
; cells by 20, in the attribute start_landscape sets in it for each level).
; Called by start_landscape and fly_in_step.
colour_play_area:
  LD HL,$B708
  LD DE,play_area_colour
  JP fill_attributes

; The game: menu, a new game, and into play
;
; Used by the routines at start and play.
;
; Jumped to by the start (start), and by play when the current player has no
; lives left. The menu (menu), a new game (new_game), a clear screen
; (clear_attributes, clear_pixels), the panel (draw_panel), the PLAYER message
; (show_player), a pause of six delays (delay), the play area cleared
; (clear_play_area), and into the play (play).
game:
  CALL menu               ; Menu, and a new game
  CALL new_game           ;
  CALL clear_attributes   ; Clear the screen and draw the panel
  CALL clear_pixels       ;
  CALL draw_panel         ;
  CALL show_player        ; Say which player is to play
  LD B,$06                ; A pause
game_0:
  CALL delay              ;
  DJNZ game_0             ;
  CALL clear_play_area    ; Clear the play area and play
  JR play_0               ;

; The play: a life, from its start to its end
;
; Used by the routine at level_done.
;
; Entered at the start of every life after the first: from its own death
; sequence once lose_life has taken a life, and from level_done at the end of a
; level. A new game enters further on, past the reset and the panel, from game.
; Resets the play (reset_for_life), goes back to the menu if the current player
; has no lives, redraws the panel, and then: puts back the ore (ore) the player
; had aboard, patches the BIT in spawn_objects_from_list and the SETs in
; ship_hits_ground_objects and beam_hits_ground_object that test and mark an
; object gone in map_object_kinds (one byte per object lying in the world) so
; that they use bit 7 for player 1 and bit 6 for player 2, and starts the level
; (start_landscape).
;
; The play loop, once a pass (about 20 a second): ship_pass, the fuel gauge
; (update_fuel_gauge), spawn_tick, update_objects (counts the death byte up,
; and much else), the random numbers (random). It ends when the death byte
; death_count reaches 12, or when launch_state is $FF: the rocket, all eight
; parts built and the ship docked, has risen (level_done).
;
; The death sequence: the landscape is stopped (scroll_down), the fuel is set
; to empty (fuel), part of draw_ship runs once and lift_jet erases the lift
; jet; then a shorter loop -- ship_pass, the pause key (check_pause), the fuel
; gauge, update_objects, carried_part, the gauge again -- runs until
; update_objects has counted the death byte up to $50. Then the death tune
; (death_tune), the play area dissolved (dissolve_and_clear), and a life is
; taken (lose_life) before going round again.
play:
  CALL reset_for_life     ; Reset the play
  LD A,(lives)            ; No lives left: back to the menu
  AND A                   ;
  JR Z,game               ;
  CALL draw_panel         ; Redraw the panel
; This entry point is used by the routine at game.
play_0:
  LD A,(ore_kept)         ; Put back the player's ore
  LD (ore),A              ;
  LD A,(player_in_play)   ; Player 1 tests bit 7 of an object's state (BIT
  LD B,A                  ; 7,(HL)), player 2 bit 6 (BIT 6,(HL))
  LD A,$7E                ;
  BIT 0,B                 ;
  JR Z,play_1             ;
  LD A,$76                ;
play_1:
  LD ($E118),A            ; Patch the test, and (with the bits for SET) the two
  OR $F0                  ; instructions that set it
  LD ($A9B8),A            ;
  LD ($ABDE),A            ;
  CALL start_landscape    ; Start the level
play_2:
  CALL ship_pass          ; A pass of the play loop
  CALL update_fuel_gauge  ;
  CALL spawn_tick         ;
  CALL update_objects     ;
  CALL random             ;
  LD A,(death_count)      ; Has the death byte reached 12?
  CP $0C                  ;
  JR NC,play_3            ;
  LD A,(launch_state)     ; Go round again unless launch_state is $FF
  INC A                   ;
  JR NZ,play_2            ;
  JP level_done           ; The level is done
play_3:
  XOR A                   ; Death: stop the landscape, the fuel gauge to empty
  LD (scroll_across),A    ;
  LD (scroll_down),A      ;
  LD HL,$BE00             ;
  LD (fuel),HL            ;
  CALL draw_trail         ; Once at the start of the death sequence
  CALL lift_jet           ;
play_4:
  CALL ship_pass          ; A pass of the death sequence
  CALL check_pause        ;
  CALL update_fuel_gauge  ;
  CALL update_objects     ;
  CALL carried_part       ;
  CALL update_fuel_gauge  ;
  LD A,(death_count)      ; Until the death byte is $50
  CP $50                  ;
  JR NZ,play_4            ;
  LD DE,death_tune        ; The death tune
  CALL play_tune          ;
  CALL dissolve_and_clear ; Dissolve the play area
  CALL lose_life          ; Take a life, and start the next
  JP play                 ;

; Take a life from the current player
;
; Used by the routine at play.
;
; Keeps the ore aboard (ore) in the player's record (+25, ore_kept), takes a
; life (+6), and if that was the last ends the player's game (game_over).
; Otherwise, with two players, hands over to the other one (swap_players).
;
; The JR Z tests the flags the DEC A leaves; LD does not touch them. With the
; DEC A taken out (a NOP poked over it, as stage 0's infinite-lives poke did)
; the JR Z picks up the zero flag left by the last DEC C of clear_play_area,
; which the death sequence has just run, and every death goes to game_over with
; the lives kept. An OR A in its place keeps the lives and tests them (run for
; the reference pages).
lose_life:
  LD A,(ore)              ; Keep the ore aboard in the record
  LD (ore_kept),A         ;
  LD A,(lives)            ; A life less; none left: game over
  DEC A                   ;
  LD (lives),A            ;
  JR Z,game_over          ;
  LD A,(player_count)     ; Two players: the other one's turn
  AND A                   ;
  CALL NZ,swap_players    ;
  RET                     ;

; The tune played when the ship has been destroyed
;
; For play_tune: one byte a note, bits 0 to 5 the note (an index into the table
; at note_table; 0 a rest) and bits 6 and 7 its length less one; $FF ends it.
death_tune:
  DEFB $1E,$1C,$1B,$19,$58,$D9,$FF

; The tune played when a game is started
;
; For play_tune, in the format of death_tune; played by menu as the menu ends.
; It ends with $FF.
start_tune:
  DEFB $2A,$2C,$2A,$27,$29,$29,$29,$25
  DEFB $E7,$FF

; Say which player is to play
;
; Used by the routines at game, game_over and swap_players.
;
; Puts the player's digit ($1B for 1, $1C for 2, from player_in_play) into the
; message at messages_and_players + 13 and prints it with print_string.
show_player:
  LD A,(player_in_play)
  ADD A,$1B
  LD (player_digit),A
  LD DE,player_message
  JP print_string

; The current player's game is over
;
; Used by the routine at lose_life.
;
; Called by lose_life when the last life has gone. Prints the player's name and
; GAME OVER (both messages at messages_and_players), puts the score in the high
; score if it beats it (check_high_score), plays the game-over tune
; (game_over_tune), waits twelve delays or until 0 is pressed, clears the play
; area and, with two players, hands over to the other one (swap_players does
; nothing if that one has no lives either). play then finds the current player
; with no lives and goes back to the menu.
game_over:
  CALL show_player           ; PLAYER n, GAME OVER
  LD DE,messages_and_players ;
  CALL print_string          ;
  CALL check_high_score   ; A new high score?
  LD DE,game_over_tune    ; The game-over tune
  CALL play_tune          ;
  LD B,$0C                ; Wait twelve delays, or until 0 is pressed
game_over_0:
  CALL delay              ;
  LD A,$EF                ;
  OUT ($FD),A             ;
  IN A,($FE)              ;
  AND $01                 ;
  JR Z,game_over_1        ;
  DJNZ game_over_0        ;
game_over_1:
  CALL clear_play_area    ; Clear the play area
  LD A,(player_count)     ; Two players: the other one's turn, if they have
  AND A                   ; lives
  CALL NZ,swap_players    ;
  RET                     ;

; The end of a level: the rocket has risen
;
; Used by the routine at play.
;
; Jumped to from the play loop (play) when launch_state is $FF, after the
; rocket has been built and has risen. Clears the play area, shows the end of
; the level (planet_secured, which also counts the level on in the record,
; +18), plays its tune (level_tune), waits fourteen delays, clears the play
; area again and the player's three flag bytes (+3 to +5, see
; messages_and_players), and starts the next life's play at play.
;
; The rocket's part of this is from the agent who read launch_state's setting;
; here, planet_secured is read counting the level on.
level_done:
  CALL clear_play_area    ; Clear the play area; the end-of-level display
  CALL planet_secured     ;
  LD DE,level_tune        ; Its tune
  CALL play_tune          ;
  LD B,$0E                ; A pause
level_done_0:
  CALL delay              ;
  DJNZ level_done_0       ;
  CALL clear_play_area    ; Clear the play area
  XOR A                   ; Clear the record's three flag bytes, and play on
  LD (player_flag_bits),A ;
  LD ($F5EB),A            ;
  LD ($F5EC),A            ;
  JP play                 ;

; Make the score the high score if it beats it
;
; Used by the routine at game_over.
;
; Compares the current player's score as printed on the panel (six characters
; from p1_score_digits) with the high score (hiscore_digits), digit by digit
; from the left, and copies it over if it is greater.
check_high_score:
  LD HL,hiscore_digits    ; The score's six digits against the high score's
  LD DE,p1_score_digits   ;
  LD B,$06                ;
check_high_score_0:
  LD A,(DE)               ; A digit less: not a high score
  CP (HL)                 ;
  RET C                   ;
  JR NZ,check_high_score_1 ; Equal: the next digit
  INC HL                   ;
  INC DE                   ;
  DJNZ check_high_score_0  ;
check_high_score_1:
  LD DE,hiscore_digits    ; Greater: the new high score
  LD HL,p1_score_digits   ;
  LD BC,$0006             ;
  LDIR                    ;
  RET                     ;

; The tune played at the end of a level
;
; For play_tune, in the format of death_tune; played by level_done. Twenty-one
; notes and the $FF that ends them.
level_tune:
  DEFB $A5,$25,$25,$25,$A9,$25,$25,$25
  DEFB $AC,$A4,$A5,$6C,$2C,$AE,$AC,$AA
  DEFB $AE,$AC,$A4,$A5,$99,$FF

; The tune played when a player's game is over
;
; For play_tune, in the format of death_tune; played by game_over. Sixteen
; notes and the $FF that ends them.
game_over_tune:
  DEFB $2E,$2C,$2A,$2C,$2A,$29,$2A,$29
  DEFB $27,$22,$1E,$22,$27,$27,$27,$27
  DEFB $FF

; Hand over to the other player
;
; Used by the routines at new_game, lose_life and game_over.
;
; Does nothing if the other player has no lives (+6 of the second record).
; Otherwise swaps the two player records, all 105 bytes, so that the current
; player is always the one at messages_and_players + 25 and the rest of the
; game never needs to know which; swaps the two score lines of the panel
; (p1_score_text and p2_score_text, 16 bytes each); and unless player_in_play
; is $99 (as new_game sets it while it puts the score lines in order) changes
; player_in_play to the other player, says PLAYER n (show_player), pauses eight
; delays and clears the play area.
swap_players:
  LD A,($F656)            ; The other player has no lives: carry on
  AND A                   ;
  RET Z                   ;
  LD DE,score               ; Swap the records
  LD HL,other_player_record ;
  LD B,$69                  ;
  CALL swap_bytes           ;
  LD DE,p1_score_text     ; Swap the score lines
  LD HL,p2_score_text     ;
  LD B,$10                ;
  CALL swap_bytes         ;
  LD A,(player_in_play)   ; Setting up: leave the current player alone
  CP $99                  ;
  RET Z                   ;
  XOR $01                 ; The other player, and say so
  LD (player_in_play),A   ;
  CALL show_player        ;
  LD B,$08                ; A pause, and clear the play area
swap_players_0:
  CALL delay              ;
  DJNZ swap_players_0     ;
  JP clear_play_area      ;

; Swap B bytes between (HL) and (DE)
;
; Used by the routine at swap_players.
;
; HL one block
; DE the other
; B how many
swap_bytes:
  LD C,(HL)
  LD A,(DE)
  LD (HL),A
  LD A,C
  LD (DE),A
  INC HL
  INC DE
  DJNZ swap_bytes
  RET

; The GAME OVER message
;
; For print_string, printed by game_over: a pixel x and y, an attribute (bit 7
; set here), a count of characters (9) and the characters (font codes: $00 to
; $19 the letters, $1A to $23 the digits, $26 a space). The PLAYER message
; follows (player_message).
messages_and_players:
  DEFB $30,$4F,$C6,$09,$06,$00,$0C,$04
  DEFB $26,$0E,$15,$04,$11

; The PLAYER message
;
; For print_string, printed by show_player and game_over: x, y, attribute, a
; count of 8 and the characters; the last of them, the player's digit, is
; player_digit.
player_message:
  DEFB $38,$67,$C5,$08    ; x, y, attribute, count
  DEFB $0F,$0B,$00,$18,$04,$11,$26 ; The word and a space

; The PLAYER message's digit
;
; The last character of player_message: $1B (the font's 1) or $1C (2), written
; by show_player from player_in_play, the current player.
player_digit:
  DEFB $00

; The current player's record: the score
;
; The current player's record is 105 ($69) bytes from here, to
; other_player_record; swap_players swaps it with the other player's at a
; change of player, so the game only ever reads and writes this one.
; clear_player_record clears it for a new game and new_game fills in the rest.
; Each field is an entry of its own; +n below is the offset from here.
;
; +0 to +2: the score, three BCD bytes, least significant first.
; test_player_shots adds BC to it.
score:
  DEFB $00,$00,$00        ; Score

; The current player's destroyed beam generators (+3 to +5)
;
; 24 bits, one for each map square (map_square_bit picks the byte and the bit):
; set when the special beam destroys a beam generator there (object kinds 6 and
; 7, beam_hits_ground_object), and tested by draw_beams, which then draws no
; beam in that square. Cleared at the end of a level (level_done).
player_flag_bits:
  DEFB $00,$00,$00

; The current player's lives (+6)
;
; 5 at a new game (new_game); one taken by lose_life, one given by
; contact_extra_life (at most 9); none left sends play back to the menu. Also
; read by print_lives for the panel and by ground_object_fires for the ground
; objects' firing rate.
lives:
  DEFB $03

; The current player's add-ons (+7 to +15): the first slot
;
; Nine bytes, one per add-on the ship can pick up, each 0 or the add-on's own
; number (1 to 9), set by draw_ship when one is fitted. build_ship_sprite
; builds the ship's picture (ship_picture) from them. The ones the code reads
; by name are entries of their own: addon_two, addon_four to addon_nine. This
; one is read by collect_pickup, build_ship_sprite and draw_ship.
addon_slots:
  DEFB $00

; Add-on 2 (+8)
;
; Set by build_ship_sprite to twice the first slot as it builds the ship, and
; read by hit_block. The byte after it, add-on 3, is not read by name.
addon_two:
  DEFB $00,$00

; Add-on 4 (+10)
;
; Read by start_attacker, build_ship_sprite (top speed across) and draw_ship
; (the side jet is drawn if it is fitted).
addon_four:
  DEFB $00

; Add-on 5 (+11)
;
; Read by start_attacker, build_ship_sprite, read_controls and lift_jet (the
; lift jet).
addon_five:
  DEFB $00

; Add-on 6 (+12)
;
; When fitted, the fuel burnt by read_controls is halved.
addon_six:
  DEFB $00

; Add-on 7 (+13)
;
; Read by special_beam_key when bit 5 of the controls (the number row) is set.
addon_seven:
  DEFB $00

; Add-on 8 (+14)
;
; Read by fire (firing).
addon_eight:
  DEFB $00

; Add-on 9 (+15)
;
; Read by collect_pickup, build_ship_sprite, hit_block and ship_pass.
addon_nine:
  DEFB $00

; The slab-and-spire load is carried (+16)
;
; 9 while the ship carries the slab and the spire (object kinds 9 and $0A,
; add-ons 10 and 11): set by collect_pickup when the slab is taken, cleared by
; carried_part when the load is put down and by start_landscape; tested by
; carried_part, which draws the load, and ship_contact (a cloud tests itself
; against the load only while it is carried). The byte after it (+17) is not
; referred to.
player_count_nine:
  DEFB $00,$00

; The current player's level (+18)
;
; From 0; counted on by planet_secured when the planet is secured.
; start_landscape picks the level's colour and data by it.
level:
  DEFB $00

; The current player's restart position (+19 to +24): the first word
;
; Three words, saved by save_restart_point as the restart point moves on and
; put back by start_landscape at the start of a life: this one for view_column,
; restart_view for view_x, restart_fine for origin_x. A new game starts from
; start_position.
restart_scroll:
  DEFW $070D

; The restart position's second word (+21)
;
; For view_x; see restart_scroll. start_landscape also reads its low byte.
restart_view:
  DEFW $B790

; The restart position's third word (+23)
;
; For origin_x, the scroll position; see restart_scroll.
restart_fine:
  DEFW $4078

; The ore the current player had aboard (+25)
;
; Kept here from ore by lose_life when a life is lost and put back by play;
; cleared by drop_part when part 6 is dropped in place.
ore_kept:
  DEFB $00

; The rocket part the current player carries (+26)
;
; $FF for none (clear_player_record, drop_part); set by collect_pickup when a
; part is picked up and to 6 by planet_secured as a planet is secured. Read by
; drop_part, load_ore (ore is collected only with part 6 aboard),
; build_ship_sprite and others.
rocket_part_carried:
  DEFB $FF

; The rocket parts delivered (+27)
;
; How many parts of the rocket have been delivered, which is also the number of
; the part due next: counted up by update_rocket_part as each one falls into
; place; read by draw_rocket, which draws that many and launches at eight, and
; by collect_pickup, which lets the ship take only the part due next. Set to 6
; by planet_secured, with rocket_part_carried, at the end of a planet.
parts_built:
  DEFB $00

; The current player's control method (+28)
;
; 0 keyboard, 1 Kempston, 2 cursor, 3 Interface II; copied from the menu by
; new_game and read by read_control_method.
control_method:
  DEFB $00

; The current player's places (+29 to +104)
;
; 19 entries of 4 bytes, filled in by deal_places at a new game and walked by
; load_map_window; bit 7 of an entry's first byte marks it done
; (collect_pickup). The entries the code names directly are entries of their
; own: place_nine, place_ten, place_eleven, place_last.
player_places:
  DEFB $00,$00,$00,$00
  DEFB $FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF,$FF
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00

; Place entry 9 (+65)
;
; Given a position by carried_part; bit 7 cleared by start_landscape.
place_nine:
  DEFB $00,$00,$00,$00

; Place entry 10 (+69)
;
; Given a position by carried_part; bit 7 set by collect_pickup and cleared by
; start_landscape.
place_ten:
  DEFB $00,$00,$00,$00

; Place entry 11 (+73), and the ones after it
;
; collect_pickup indexes the entries from here by the part's number.
place_eleven:
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00
  DEFB $00,$00,$00,$00

; The last place entry (+101)
;
; Filled in again by planet_secured (through deal_places's second entry point)
; when a planet is secured.
place_last:
  DEFB $00,$00,$00,$00

; The other player's record
;
; Laid out as score. With one player its lives (+6) are 0, so swap_players
; never swaps it in. new_game writes its lives, control method (+28) and object
; table (+29) directly.
other_player_record:
  DEFB $00,$00,$00,$00,$00,$00,$03,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$0D,$07,$90,$B7,$78
  DEFB $40,$00,$FF,$00,$00,$00,$00,$00
  DEFB $00,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00

; The ship's picture, built in RAM
;
; 300 bytes ($12C), cleared by start_landscape and built by build_ship_sprite
; from the add-ons the player has picked up (it starts from 84 bytes copied
; from bare_ship to 156 bytes in, and adds each part); six bytes a row, bottom
; row first like the game's other graphics. ship_graphic points at ship_picture
; while a rocket part hangs from the ship (bit 6 of part_being_fitted), the
; picture then five rows taller, and otherwise 30 bytes (five rows) on
; (toggle_carried_part); and load_ore adds rows to it from rocket_tank_graphic
; as the ore aboard (ore) grows.
ship_picture:
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00

; Row 50 of the ship's picture
;
; Six bytes after ship_picture's 300, and not spare: add-on 9
; (build_ship_sprite) grows the picture up to row 50 (51 rows with every add-on
; fitted, simulated), so its top row and its mask's are drawn here, and the
; ship is drawn from here up to its top: the figure's top row puts $30 in the
; third byte, spare_after_ship + 2, and leaves the rest nought (watched for the
; reference pages). Zero in the snapshot; nothing clears it, and nothing else
; uses it.
spare_after_ship:
  DEFS $06

; Build the landscape pieces' shifted copies
;
; Used by the routine at sprite_buffer_two.
;
; Called once, at the start (build_shift_tables), with the shift tables from
; shift_tables in place. Clears the work bytes from scratch_count, 38 of them,
; and makes, for each of the nine stored terrain-piece graphics, its copies
; shifted right by 2, 4 and 6 pixels, one after another at the address given:
; with shift_slope_piece for the slopes and the wall, with shift_flat_piece for
; the two flat pieces. The three ceiling slopes are made with piece_step_x set,
; which pads them with the checkerboard on the left instead of the right.
;
; The tape holds the copies' places as zeros (the generator ORs into them),
; except that the flat pieces' copies are only partly made here; the rest of
; them came on the tape (see shift_flat_piece). Each graphic starts with a
; header (read_piece_header), which is why the source addresses here are two or
; three bytes before those in the tables at piece_blitters_shift2.
;
; This routine and the ones after it to shift_slope_piece's end run once.
; Afterwards their bytes are reused: a sprite-compositing buffer of up to 256
; bytes starts 21 bytes into this routine, inside the operand of a CALL, so it
; cannot have a label of its own (copy_box_in copies into it with LDI and
; dissolve_sprite reads it back; old_beam_frame builds a sprite there and
; new_beam_frame another from its 128th byte, sprite_buffer_two), over the end
; of this routine and the ones up to bit_reverse_table; and from
; bit_reverse_table the bit-reversed table build_bit_reverse makes, over the
; rest.
build_shifted_pieces:
  LD HL,scratch_count     ; Clear the work bytes scratch_count to
  LD B,$26                ; basic_leftovers
  CALL clear_bytes        ;
  XOR A                   ; Floors: no padding on the left
  LD (piece_step_x),A     ;
  LD HL,slope_2_shifted   ; Direction 2 (one byte wide, 9 rows), shifted to
  EXX                     ; slope_2_shifted
  LD HL,slope_2_gfx       ;
  CALL shift_slope_piece  ;
  LD HL,slope_1_shifted   ; Direction 1 (two bytes wide, 9 rows), to
  EXX                     ; slope_1_shifted
  LD HL,slope_1_gfx       ;
  CALL shift_slope_piece  ;
  LD HL,slope_3_shifted   ; Direction 3 (one byte wide, 17 rows), to
  EXX                     ; slope_3_shifted
  LD HL,slope_3_gfx       ;
  CALL shift_slope_piece  ;
  LD HL,wall_shifted      ; Direction 14 (the wall), to wall_shifted
  EXX                     ;
  LD HL,wall_gfx          ;
  CALL shift_slope_piece  ;
  LD HL,flat_piece_shifted ; Direction 0 (flat), to flat_piece_shifted
  EXX                      ;
  LD HL,flat_piece_gfx     ;
  CALL shift_flat_piece    ;
  LD HL,flat_piece_two_shifted ; Direction 7 (the flat ceiling), to
  EXX                          ; flat_piece_two_shifted
  LD HL,flat_piece_two_gfx     ;
  CALL shift_flat_piece        ;
  OR $FF                  ; Ceilings: checkerboard on the left
  LD (piece_step_x),A     ;
  LD HL,slope_9_shifted   ; Direction 9, to slope_9_shifted
  EXX                     ;
  LD HL,slope_9_gfx       ;
  CALL shift_slope_piece  ;
  LD HL,slope_8_shifted   ; Direction 8, to slope_8_shifted
  EXX                     ;
  LD HL,slope_8_gfx       ;
  CALL shift_slope_piece  ;
  LD HL,slope_10_shifted  ; Direction 10, to slope_10_shifted
  EXX                     ;
  LD HL,slope_10_gfx      ;
  JP shift_slope_piece    ;

; Build the bit-reversed table at bit_reverse_table
;
; Used by the routine at sprite_buffer_two.
;
; Jumped to at the end of build_shift_tables, after build_shifted_pieces has
; run: bit_reverse_table + n gets n with its bits in the opposite order, for
; mirroring graphics: the ship when it faces left, the landscape's
; left-climbing pieces (blit_mirror_two, blit_mirror_one), and the sprite
; routines mirror_ship_sprite, draw_ship, blit_mirrored_left_clip and others.
; It overwrites the start-up routines from bit_reverse_table to
; shift_slope_piece's end, which are done with by then; the code map shows them
; because the snapshot was taken before the game ran.
build_bit_reverse:
  LD C,$00                ; From bit_reverse_table, for n = 0 to 255
  LD HL,bit_reverse_table ;
build_bit_reverse_0:
  LD B,$08                 ; Shift n's bits out of the top of D and into the
  LD D,C                   ; top of A
  XOR A                    ;
build_bit_reverse_1:
  SLA D                    ;
  RR A                     ;
  DJNZ build_bit_reverse_1 ;
  LD (HL),A                 ; Store, and the next
  INC HL                    ;
  INC C                     ;
  JR NZ,build_bit_reverse_0 ;
  RET

; Build the shift tables
;
; Used by the routine at start.
;
; Called once by the start (start). Makes three pairs of pages: for a shift of
; 2 pixels, shift_tables + n is n shifted right two bits and the next page's
; byte n the two bits that fall off the right, at the top of a byte; for 4,
; loader_copy and the page after it; for 6, loader_leftover_charset and the
; page after it. A byte drawn shifted is then two lookups: the left-hand screen
; byte gets the high page, the right-hand one the low page. These pages
; overwrite the end of the loaded block, the loader's copy routine at
; loader_copy and the loader's stack below loader_leftover_charset among it.
; Then the landscape pieces are shifted with them (build_shifted_pieces) and
; the bit-reversed table made (build_bit_reverse).
;
; The tables are used afterwards too: toggle_carried_part reads the loader_copy
; page, clamp_climb and clamp_object_speed the page after it.
build_shift_tables:
  LD HL,shift_tables      ; From shift_tables; two bits first
  LD B,$02                ;
; This entry point is used by the routine at sprite_buffer_two.
build_shift_tables_0:
  LD C,$00                ; DE = n shifted right B bits, across two bytes
; This entry point is used by the routine at sprite_buffer_two.
build_shift_tables_1:
  LD D,C
  LD E,$00
  LD A,B
build_shift_tables_2:
  SRL D
  RR E
  DEC A
  JR NZ,build_shift_tables_2 ; }
  LD (HL),D               ; The high part in this page, the low part in the
  INC H                   ; next
  LD (HL),E               ;

; Build the shift tables (continued); later, the second sprite buffer
;
; The rest of build_shift_tables's loop. After the start-up these bytes are the
; second half of the sprite-compositing buffer that begins inside
; build_shifted_pieces: new_beam_frame builds a sprite here (and old_beam_frame
; one 128 bytes lower).
sprite_buffer_two:
  DEC H                      ; Back to the high page; all 256 values
  INC HL                     ;
  INC C                      ;
  LD A,C                     ;
  AND A                      ;
  JR NZ,build_shift_tables_1 ;
  INC H                      ; The next pair of pages, two bits more, up to six
  INC B                      ;
  INC B                      ;
  LD A,B                     ;
  CP $08                     ;
  JR NZ,build_shift_tables_0 ;
  CALL build_shifted_pieces ; Shift the landscape pieces, and the bit-reversed
  JP build_bit_reverse      ; table

; Read a slope piece's header
;
; Used by the routine at shift_slope_piece.
;
; For shift_slope_piece: a slope's header is three bytes -- the number of rows
; in each variant, halved and rounded up (to row_count, and row_count_spare to
; reload it), the number of pairs of rows (row pairs to scratch_count and
; ground_cell), and the width in bytes (C). A flat piece's header is the last
; two of these (entered at its fourth instruction by shift_flat_piece). D is
; set to $FA, the first high page of the shift tables.
;
;   HL the header
; O:HL the graphic
; O:C its width in bytes
; O:D $FA
read_piece_header:
  LD A,(HL)               ; Rows in each variant, halved
  LD (row_count),A        ;
  LD (row_count_spare),A  ;
  INC HL                  ;
; This entry point is used by the routine at shift_flat_piece.
read_piece_header_0:
  LD A,(HL)               ; Pairs of rows
  LD (scratch_count),A    ;
  LD (ground_cell),A      ;
  INC HL                  ;
  LD D,$FA                ; The shift tables' first high page
  LD C,(HL)               ; The width in bytes
  INC HL                  ;
  RET                     ;

; Shift a graphic byte into a row being made left to right
;
; Used by the routines at shift_flat_piece and shift_slope_piece.
;
; ORs the high part of the byte at HL into the byte at HL' and moves on to the
; next, then ORs the low part into that one: the byte that spills over is left
; there for the next byte's high part to join.
;
; HL the graphic byte
; D the high page of the shift tables
; HL' the copy being made
shift_byte_forward:
  LD E,(HL)               ; High part, into this byte; on to the next
  LD A,(DE)               ;
  EXX                     ;
  OR (HL)                 ;
  LD (HL),A               ;
  INC HL                  ;
  EXX                     ;
  INC D                   ; Low part, into the next byte
  LD A,(DE)               ;
  DEC D                   ;
  EXX                     ;
  OR (HL)                 ;
  LD (HL),A               ;
  EXX                     ;
  RET                     ;

; OR the checkerboard's high part into the copy, and move on
;
; Used by the routine at shift_slope_piece.
;
; Ends a row made left to right with the checkerboard's ($55) bits shifted in
; on the right. Entered at its third instruction with A ready, and at its
; fourth from the alternate set, by shift_flat_piece and shift_slope_piece.
pad_right_checker:
  LD E,$55                ; The high part of $55
  LD A,(DE)               ;
; This entry point is used by the routines at bit_reverse_table and
; shift_slope_piece.
pad_right_checker_0:
  EXX                     ; OR it in, and move on
; This entry point is used by the routine at bit_reverse_table.
pad_right_checker_1:
  OR (HL)
  LD (HL),A
  INC HL
  EXX
  RET                     ; }

; An INC HL never reached
;
; Nothing jumps here; pad_right_checker returns just before it.
unused_inc_hl:
  DEFB $23

; Fetch the low part of a graphic byte
;
; Used by the routine at shift_flat_piece.
;
; B = C first (the width), when entered here; at its second instruction just A
; = the low part of the byte at HL, its high part being left for the next call
; (shift_byte_high) to fetch.
;
; HL the graphic byte
; D the high page of the shift tables
shift_byte_low:
  LD B,C                  ; B is the width
; This entry point is used by the routines at bit_reverse_table and
; shift_slope_piece.
shift_byte_low_0:
  LD E,(HL)               ; A = the byte's low part
  INC D                   ;
  LD A,(DE)               ;
  DEC D                   ;
  RET                     ;

; OR a graphic byte's high part into the copy, and step to the next graphic
; byte
;
; Used by the routines at bit_reverse_table and shift_slope_piece.
;
; For a row being made right to left: the high part of the byte last fetched
; (E) goes into the copy's current byte, which is not moved on; HL steps to the
; next graphic byte. Entered at its third instruction with A ready.
shift_byte_high:
  INC HL                  ; Next graphic byte; A = the last one's high part
  LD A,(DE)               ;
; This entry point is used by the routine at shift_slope_piece.
shift_byte_high_0:
  EXX                     ; OR it into the copy
  OR (HL)                 ;
  LD (HL),A               ;
  EXX                     ;
  RET                     ;

; Start a graphic's next shifted copy
;
; Used by the routine at shift_slope_piece.
;
; Reloads the row counts from their spares (row_count_spare to row_count when
; entered here, ground_cell to scratch_count from its third instruction) and
; moves D on to the next pair of shift tables, two pages up. Returns with zero
; set when D has gone past $FF, that is, after the copy shifted by 6.
next_shift:
  LD A,(row_count_spare)  ; The rows in each variant
  LD (row_count),A        ;
; This entry point is used by the routine at bit_reverse_table.
next_shift_0:
  LD A,(ground_cell)      ; The pairs of rows
  LD (scratch_count),A    ;
  LD A,D                  ; The next shift; zero after the last
  ADD A,$02               ;
  LD D,A                  ;
  AND A                   ;
  RET                     ;

; Make a flat piece's shifted copies
;
; Used by the routine at build_shifted_pieces.
;
; For build_shifted_pieces, the two flat pieces (directions 0 and 7). A flat
; piece is three bytes wide and tiles: the ground under it repeats every 24
; pixels. So its rows are rotated rather than shifted: the bits that would fall
; off the right-hand end come back in at the left (the byte that would hold
; them is cleared and its bits ORed into the row's first byte), and nothing is
; added to the width. The row pairs alternate as in the blitter blit_flat_step:
; left to right, then right to left. After each copy, HL' skips 48 bytes: only
; the first 12 rows of each 28-row copy are made here, the other 16 rows of
; each having come on the tape already shifted (read from the simulator). The
; 12 made are the three 4-row variants of the step, the ground that repeats and
; so can be rotated; the 16 on the tape are the four end caps, already shifted
; (checked in the simulator for the Graphics page) -- presumably because a cap
; does not tile, so rotating it would wrap its edge round to the wrong side
; (assumed).
;
; At the end it patches a byte in the last row of each flat piece's copy
; shifted by 6 (flat_piece_shifted and flat_piece_two_shifted; to $5C and $40),
; perhaps to mend a pixel the rotation got wrong (not checked).
;
; HL the piece's header (two bytes: pairs of rows, width)
; HL' where the copy shifted by 2 goes; the copies shifted by 4 and 6 follow,
;     84 bytes apart
shift_flat_piece:
  CALL read_piece_header_0 ; Read the header
; This entry point is used by the routine at bit_reverse_table.
shift_flat_piece_0:
  PUSH HL                 ; Back here for each shift
; This entry point is used by the routine at bit_reverse_table.
shift_flat_piece_1:
  LD B,C                  ; A row left to right: width + 1 bytes shifted in
  INC B                   ;
shift_flat_piece_2:
  CALL shift_byte_forward ;
  INC HL                  ;
  DJNZ shift_flat_piece_2 ;
  EXX                     ; Rotate: the spill clears and ORs into the row's
  LD (HL),$00             ; first byte
  DEC HL                  ;
  DEC HL                  ;
  DEC HL                  ;
  OR (HL)                 ;
  LD (HL),A               ;
  INC HL                  ;
  INC HL                  ;
  INC HL                  ;
  EXX                     ;
  CALL shift_byte_low     ; A row right to left: keep the first byte's low part
  LD (pieces_left),A      ;

; Make a flat piece's shifted copies (continued); later, the bit-reversed table
;
; The rest of shift_flat_piece. Once the start-up is over this is the
; bit-reversed table build_bit_reverse builds: bit_reverse_table + n holds n
; with its bits reversed, 256 bytes over the end of shift_flat_piece and all of
; shift_slope_piece, which have done their work by then. The game reads it with
; LD B,$F9 and the byte in C, to mirror the ship (mirror_ship_sprite), the
; left-climbing landscape steps (blit_mirror_two, blit_mirror_one) and other
; sprites (draw_ship, blit_mirrored_left_clip).
bit_reverse_table:
  INC B                   ; One byte more than the width
bit_reverse_table_0:
  CALL shift_byte_high     ; Shift the bytes in
  CALL shift_byte_low_0    ;
  CALL pad_right_checker_0 ;
  DJNZ bit_reverse_table_0 ;
  INC D                   ; Take out the spill of the next row's byte
  LD A,(DE)               ;
  DEC D                   ;
  EXX                     ;
  DEC HL                  ;
  XOR (HL)                ;
  LD (HL),A               ;
  LD A,(pieces_left)       ; And put the first byte's low part in the last
  CALL pad_right_checker_1 ; byte, rotating
  LD A,(scratch_count)     ; The next pair of rows
  DEC A                    ;
  LD (scratch_count),A     ;
  JR NZ,shift_flat_piece_1 ;
  CALL next_shift_0        ; The next shift, 48 bytes further on
  EXX                      ;
  LD DE,$0030              ;
  ADD HL,DE                ;
  EXX                      ;
  POP HL                   ;
  JR NZ,shift_flat_piece_0 ;
  LD A,$5C                ; Two bytes of the copies mended
  LD ($EB34),A            ;
  LD A,$40                ;
  LD ($EC30),A            ;
  RET                     ;

; Make a slope piece's shifted copies
;
; Used by the routine at build_shifted_pieces.
;
; For build_shifted_pieces, the slopes and the wall. A slope is made one byte
; wider than its graphic, row by row, the rows alternating left to right and
; right to left like the blitters that draw them; the open side of each row is
; filled with the checkerboard's bits ($55 on rows made left to right, $AA on
; the others), on the right normally and on the left for the ceilings
; (piece_step_x set). The header's first count (row_count) cuts the zig-zag
; after each variant: a variant of 9 rows is 5 rows left to right and 4 back,
; so every variant begins with a row made left to right, as the blitter
; starting there expects.
;
; The pieces' graphics are packed so tightly that each copy reads a few bytes
; past its graphic's end (into the next graphic's header, or into the first
; copy made), giving a fourth, partial variant that the game never draws.
;
; HL the piece's header (three bytes; see read_piece_header)
; HL' where the copy shifted by 2 goes; the copies shifted by 4 and 6 follow it
;     directly
shift_slope_piece:
  CALL read_piece_header  ; Read the header
shift_slope_piece_0:
  PUSH HL                 ; Back here for each shift
shift_slope_piece_1:
  LD B,C                   ; A row left to right; ceilings: the checkerboard on
  LD A,(piece_step_x)      ; the left first
  AND A                    ;
  JR Z,shift_slope_piece_2 ;
  LD E,$55                 ;
  INC D                    ;
  LD A,(DE)                ;
  DEC D                    ;
  EXX                      ;
  OR (HL)                  ;
  LD (HL),A                ;
  EXX                      ;
shift_slope_piece_2:
  CALL shift_byte_forward  ; The row's bytes shifted in
  INC HL                   ;
  DJNZ shift_slope_piece_2 ;
  LD A,(piece_step_x)      ; Ceilings: the right-hand byte is left with the
  AND A                    ; spill only
  JR Z,shift_slope_piece_3 ;
  EXX                      ;
  INC HL                   ;
  EXX                      ;
  JR shift_slope_piece_4   ;
shift_slope_piece_3:
  CALL pad_right_checker  ; Floors: the checkerboard's bits on the right
shift_slope_piece_4:
  LD A,(row_count)         ; The variant's last row? Then no row back
  DEC A                    ;
  LD (row_count),A         ;
  JR Z,shift_slope_piece_8 ;
  LD A,(piece_step_x)       ; A row right to left; first style: the
  AND A                     ; checkerboard on the right first
  JR NZ,shift_slope_piece_5 ;
  LD E,$AA                  ;
  LD A,(DE)                 ;
  CALL shift_byte_high_0    ;
shift_slope_piece_5:
  LD B,C                   ; The row's bytes shifted in, right to left
shift_slope_piece_6:
  CALL shift_byte_low_0    ;
  CALL pad_right_checker_0 ;
  CALL shift_byte_high     ;
  DJNZ shift_slope_piece_6 ;
  LD A,(piece_step_x)      ; Ceilings: the checkerboard on the left
  AND A                    ;
  EXX                      ;
  JR Z,shift_slope_piece_7 ;
  EXX                      ;
  LD E,$AA                 ;
  INC D                    ;
  LD A,(DE)                ;
  DEC D                    ;
  EXX                      ;
  OR (HL)                  ;
  LD (HL),A                ;
shift_slope_piece_7:
  INC HL                  ; On past the row's last byte
  EXX                     ;
  JR shift_slope_piece_9  ;
shift_slope_piece_8:
  LD A,(row_count_spare)  ; Start the next variant
  LD (row_count),A        ;
shift_slope_piece_9:
  LD A,(scratch_count)      ; The next pair of rows
  DEC A                     ;
  LD (scratch_count),A      ;
  JR NZ,shift_slope_piece_1 ;
  POP HL                    ; The next shift
  CALL next_shift           ;
  JR NZ,shift_slope_piece_0 ;
  RET                       ;

; The rest of the bit-reversed table
;
; The bit-reversed table build_bit_reverse makes runs from bit_reverse_table to
; the end of this block, over the start-up routines shift_flat_piece and
; shift_slope_piece, which are finished with by then; the snapshot, taken
; before the game ran, holds zeros here. The shift tables follow
; (shift_tables).
bit_reverse_table_end:
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
